1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <title>Pulsing Circle</title>
9	  <style>
10	    :root {
11	      --circle-hue: #8ec5ff;
12	      --circle-core: #4a7dd9;
13	      --circle-shadow: #1f3a75;
14	      --cycle: 2.5s;
15	    }
16	    * {
17	      margin: 0;
18	      padding: 0;
19	      box-sizing: border-box;
20	    }
21	    body {
22	      width: 100vw;
23	      height: 100vh;
24	      height: 100dvh;
25	      display: flex;
26	      flex-direction: column;
27	      justify-content: center;
28	      align-items: center;
29	      gap: 24px;
30	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
31	      overflow: hidden;
32	    }
33	    svg {
34	      width: min(400px, 80vmin);
35	      height: min(400px, 80vmin);
36	      overflow: visible;
37	      cursor: pointer;
38	      user-select: none;
39	      -webkit-tap-highlight-color: transparent;
40	      transition: filter 0.3s ease;
41	    }
42	    svg:hover {
43	      filter: brightness(1.08);
44	    }
45	    svg:focus-visible {
46	      outline: 2px solid var(--circle-hue);
47	      outline-offset: 8px;
48	      border-radius: 50%;
49	    }
50	    .ambient {
51	      fill: var(--circle-hue);
52	      opacity: 0.12;
53	      filter: blur(30px);
54	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
55	      transform-origin: 200px 200px;
56	      will-change: transform, opacity;
57	    }
58	    .core {
59	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
60	      transform-origin: 200px 200px;
61	      filter: url(#glow);
62	      will-change: transform, opacity;
63	    }
64	    .highlight {
65	      fill: url(#highlightGradient);
66	      transform-origin: 200px 200px;
67	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
68	      pointer-events: none;
69	      will-change: transform, opacity;
70	    }
71	    .ring {
72	      fill: none;
73	      stroke: var(--circle-hue);
74	      stroke-width: 2.5;
75	      transform-origin: 200px 200px;
76	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
77	      will-change: transform, opacity, stroke-width;
78	    }
79	    .ring--delay-1 {
80	      animation-delay: calc(var(--cycle) / 3);
81	    }
82	    .ring--delay-2 {
83	      animation-delay: calc(var(--cycle) / 3 * 2);
84	    }
85	    @keyframes pulse {
86	      0%, 100% {
87	        transform: scale(1);
88	        opacity: 0.9;
89	      }
90	      50% {
91	        transform: scale(1.05);
92	        opacity: 1;
93	      }
94	    }
95	    @keyframes breathe {
96	      0%, 100% {
97	        transform: scale(0.95);
98	        opacity: 0.1;
99	      }
100	      50% {
101	        transform: scale(1.1);
102	        opacity: 0.18;
103	      }
104	    }
105	    @keyframes ripple {
106	      0% {
107	        transform: scale(1);
108	        opacity: 0.6;
109	        stroke-width: 2.5;
110	      }
111	      100% {
112	        transform: scale(1.35);
113	        opacity: 0;
114	        stroke-width: 0.5;
115	      }
116	    }
117	    body.paused .core,
118	    body.paused .ring,
119	    body.paused .ambient,
120	    body.paused .highlight {
121	      animation-play-state: paused;
122	    }
123	    @media (prefers-reduced-motion: reduce) {
124	      .core, .ring, .ambient, .highlight {
125	        animation-play-state: paused;
126	      }
127	    }
128	    .speed-label {
129	      color: var(--circle-hue);
130	      font-family: system-ui, sans-serif;
131	      font-size: 0.85rem;
132	      letter-spacing: 0.05em;
133	      opacity: 0.85;
134	      user-select: none;
135	      text-align: center;
136	    }
137	    .hint {
138	      display: block;
139	      margin-top: 4px;
140	      font-size: 0.7rem;
141	      opacity: 0.85;
142	    }
143	    .controls {
144	      display: flex;
145	      align-items: center;
146	      gap: 12px;
147	    }
148	    .pause-btn {
149	      display: inline-flex;
150	      align-items: center;
151	      justify-content: center;
152	      width: 36px;
153	      height: 36px;
154	      padding: 0;
155	      border-radius: 50%;
156	      border: 1px solid var(--circle-hue);
157	      background: transparent;
158	      color: var(--circle-hue);
159	      cursor: pointer;
160	      transition: background 0.2s ease;
161	    }
162	    .pause-btn:hover {
163	      background: rgba(142, 197, 255, 0.15);
164	    }
165	    .pause-btn:focus-visible {
166	      outline: 2px solid var(--circle-hue);
167	      outline-offset: 2px;
168	    }
169	    .pause-btn svg {
170	      width: 14px;
171	      height: 14px;
172	    }
173	  </style>
174	</head>
175	<body>
176	  <svg id="ae683f770" viewBox="0 0 400 400" role="button" tabindex="0" aria-label="Pulsing blue circle animation. Click or press Enter to change pulse speed." aria-describedby="speedText">
177	    <title>Pulsing blue circle animation</title>
178	    <defs>
179	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
180	        <stop offset="0%" stop-color="#8ec5ff"/>
181	        <stop offset="55%" stop-color="#4a7dd9"/>
182	        <stop offset="100%" stop-color="#1f3a75"/>
183	      </radialGradient>
184	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
185	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
186	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
187	      </radialGradient>
188	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
189	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
190	        <feColorMatrix in="blur" type="matrix"
191	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
192	        <feMerge>
193	          <feMergeNode in="tintedBlur"/>
194	          <feMergeNode in="SourceGraphic"/>
195	        </feMerge>
196	      </filter>
197	    </defs>
198	    <circle class="ambient" cx="200" cy="200" r="160"/>
199	    <circle class="ring" cx="200" cy="200" r="140"/>
200	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
201	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
202	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
203	    <circle class="highlight" cx="200" cy="200" r="140"/>
204	  </svg>
205	  <div class="controls">
206	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation">
207	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
208	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
209	      </svg>
210	    </button>
211	    <p class="speed-label" id="speedLabel" aria-live="polite">
212	      <span id="speedText">Normal speed</span>
213	      <span class="hint">Click circle to change speed</span>
214	    </p>
215	  </div>
216	  <script>
217	    const svg = document.getElementById('ae683f770');
218	    const speedText = document.getElementById('speedText');
219	    const pauseBtn = document.getElementById('pauseBtn');
220	    const pauseIcon = document.getElementById('pauseIcon');
221	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
222	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
223	    const speeds = [
224	      { value: '2.5s', name: 'Normal speed' },
225	      { value: '1.2s', name: 'Fast speed' },
226	      { value: '4.5s', name: 'Slow speed' },
227	    ];
228	    let speedIndex = 0;
229	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
230	    let manuallyPaused = reducedMotionQuery.matches;
231	
232	    function updateLabels() {
233	      const { name } = speeds[speedIndex];
234	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
235	    }
236	
237	    function cycleSpeed() {
238	      speedIndex = (speedIndex + 1) % speeds.length;
239	      const { value } = speeds[speedIndex];
240	      svg.style.setProperty('--cycle', value);
241	      // Restart animations from the beginning so the new speed feels immediate
242	      // instead of jumping mid-cycle.
243	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
244	        el.style.animation = 'none';
245	        void el.offsetWidth;
246	        el.style.animation = '';
247	      });
248	      updateLabels();
249	    }
250	
251	    function applyPauseState() {
252	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
253	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
254	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
255	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
256	      updateLabels();
257	    }
258	
259	    function togglePause() {
260	      manuallyPaused = !manuallyPaused;
261	      applyPauseState();
262	    }
263	
264	    svg.addEventListener('click', cycleSpeed);
265	    svg.addEventListener('keydown', (e) => {
266	      if (e.key === 'Enter' || e.key === ' ') {
267	        e.preventDefault();
268	        cycleSpeed();
269	      }
270	    });
271	
272	    pauseBtn.addEventListener('click', togglePause);
273	
274	    document.addEventListener('visibilitychange', () => {
275	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
276	    });
277	
278	    reducedMotionQuery.addEventListener('change', (e) => {
279	      manuallyPaused = e.matches;
280	      applyPauseState();
281	    });
282	
283	    applyPauseState();
284	  </script>
285	</body>
286	</html>
